                          n.titleEn.toLowerCase().includes(sq) ||
                          n.summaryBn.toLowerCase().includes(sq) ||
                          n.summaryEn.toLowerCase().includes(sq) ||
                          n.source.toLowerCase().includes(sq) ||
                          n.tags.some(t => t.toLowerCase().includes(sq))
